    const openPrivacy = function (event) {
        event.preventDefault();
        modal.classList.add("is-open");
        modal.setAttribute("aria-hidden", "false");
        document.body.style.overflow = "hidden";
    };

    const closePrivacy = function () {
        modal.classList.remove("is-open");
        modal.setAttribute("aria-hidden", "true");
        document.body.style.overflow = "";
    };

    document.querySelectorAll("[data-open-privacy]").forEach(function (link) {
        link.addEventListener("click", openPrivacy);
    });

    modal.querySelectorAll("[data-close-privacy]").forEach(function (el) {
        el.addEventListener("click", closePrivacy);
    });

    document.addEventListener("keydown", function (event) {
        if (event.key === "Escape" && modal.classList.contains("is-open")) {
            closePrivacy();
        }
    });
});
</script>
